  const continueWithGoogle=async()=>{setBusy(true);setError('');setNotice('');try{const {error:e}=await supabase.auth.signInWithOAuth({provider:'google',options:{redirectTo:'https://azmeyra-store.vercel.app/account',queryParams:{prompt:'select_account'}}});if(e)throw e;}catch(e){setError(e.message||'Google sign-in could not be started.');setBusy(false);}};
  const saveProfile=async()=>{setProfileBusy(true);setError('');const {error:e}=await supabase.from('profiles').update({full_name:profile.full_name.trim(),phone:profile.phone.trim(),updated_at:new Date().toISOString()}).eq('id',session.user.id);if(e)setError(e.message);else setNotice('Profile updated successfully.');setProfileBusy(false);};
