  const setDefault=async id=>{await supabase.from('customer_addresses').update({is_default:false}).eq('user_id',session.user.id);const {error:e}=await supabase.from('customer_addresses').update({is_default:true}).eq('id',id);if(e)setError(e.message);await loadAccount();};
