function TrackOrder(){const [id,setId]=useState('');const [phone,setPhone]=useState('');const [order,setOrder]=useState(null);const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const lookup=async event=>{event.preventDefault();setBusy(true);setMessage('');setOrder(null);try{const {data,error}=await supabase.rpc('track_guest_order',{p_order_number:id.trim().toUpperCase(),p_phone:phone.trim()});if(error)throw error;if(!data){setMessage('No order matched. Check your order number and phone number.');return;}setOrder(data);}catch(error){setMessage(error.message||'Could not look up this order. Please try again.');}finally{setBusy(false);}};return <div className="page-wrap"><div className="shop-intro"><span className="eyebrow">ORDER SUPPORT</span><h1>Track your <em>order.</em></h1><p>Enter your order number and the phone number used at checkout.</p></div><div className="simple-panel"><form onSubmit={lookup}><label>Order number<input value={id} onChange={event=>setId(event.target.value)} placeholder="e.g. AZ12345678" required/></label><label>Phone number<input value={phone} onChange={event=>setPhone(event.target.value)} placeholder="01XXXXXXXXX" inputMode="tel" required/></label><button className="button button-dark" type="submit" disabled={busy}>{busy?'Checking…':'Track order'} <ArrowRight/></button></form>{message&&<p className="form-hint" role="alert">{message}</p>}{order&&<div className="order-history-card"><b>{order.order_number}</b><span>{order.status}</span><p>Total: {money(order.total)}</p><p>Delivery fee: {money(order.delivery_fee)}</p><p>Items: {order.item_count}</p><p>Placed: {new Date(order.created_at).toLocaleString()}</p></div>}</div></div>}

function WishlistPage({products,wishlist,onToggleWishlist,onAdd}){const saved=products.filter(product=>wishlist.includes(product.id));return <div className="page-wrap"><div className="shop-intro"><span className="eyebrow">THE PIECES YOU SAVED</span><h1>Your wish <em>list.</em></h1><p>A little collection of things you love.</p></div>{saved.length?<ProductGrid products={saved} wishlist={wishlist} onToggleWishlist={onToggleWishlist} onAdd={onAdd}/>:<div className="empty-state"><Heart/><h2>Nothing saved just yet.</h2><p>Tap the little heart on a piece to keep it close.</p><Link className="button button-dark" to="/shop">Explore the collection <ArrowUpRight/></Link></div>}</div>}

function AboutPage(){return <div className="page-wrap story-page"><div className="shop-intro"><span className="eyebrow">A NOTE FROM AZMEYRA</span><h1>Style should feel<br/><em>like coming home.</em></h1><p>Not more. Just more meaningful.</p></div><div className="about-grid"><img src="https://images.unsplash.com/photo-1490481651871-ab68de25d43d?w=1400" alt="Thoughtful fashion styling"/><div><span className="eyebrow">OUR POINT OF VIEW</span><h2>For the woman<br/>who is <em>all of it.</em></h2><p>AZMEYRA is a considered edit of ladieswear for the many moments that make up your day. We believe getting dressed should feel personal, effortless and quietly beautiful.</p><p>From everyday essentials to pieces for the celebrations you will remember, each selection is made to help you express your own sense of style.</p><Link className="button button-dark" to="/shop">Explore the edit <ArrowRight/></Link></div></div><div className="values-row"><div><span>01</span><b>Thoughtful selection</b><p>Pieces chosen for their details, comfort and timeless appeal.</p></div><div><span>02</span><b>Everyday elegance</b><p>Style that works with the rhythm of real life.</p></div><div><span>03</span><b>Personal expression</b><p>Your wardrobe should always feel like your own.</p></div></div></div>}

function ContactPage(){const [sending,setSending]=useState(false);const [notice,setNotice]=useState('');const [noticeError,setNoticeError]=useState(false);const submit=async event=>{event.preventDefault();const formElement=event.currentTarget;setSending(true);setNotice('');setNoticeError(false);const form=new FormData(formElement);try{const {error}=await supabase.from('contact_messages').insert({name:String(form.get('name')).trim(),contact:String(form.get('contact')).trim(),subject:String(form.get('subject')),message:String(form.get('message')).trim()});if(error)throw error;formElement.reset();setNotice('Thank you. Your message has been sent to AZMEYRA.');}catch(error){setNotice(error.message||'Message could not be sent. Please try again.');setNoticeError(true);}finally{setSending(false);}};return <div className="page-wrap contact-page"><div className="shop-intro"><span className="eyebrow">WE ARE HERE FOR YOU</span><h1>Let's talk <em>lovely.</em></h1><p>For product questions, sizing advice or delivery updates, send us a note.</p></div><div className="contact-layout"><div className="contact-details"><div><Mail/><span><b>Write to us</b><small>hello@azmeyra.com</small></span></div><div><PhoneIcon/><span><b>Call or WhatsApp</b><small>Share your preferred contact number to activate this link.</small></span></div><div><Clock3/><span><b>Customer care</b><small>Saturday – Thursday · 10 AM – 7 PM</small></span></div><div><MapPin/><span><b>Based in Bangladesh</b><small>Delivery available nationwide</small></span></div></div><form className="contact-form" onSubmit={submit}><label>Your name<input name="name" placeholder="Your name" minLength="2" maxLength="100" required/></label><label>Email or phone<input name="contact" placeholder="How can we reach you?" minLength="5" maxLength="160" required/></label><label>What can we help with?<select name="subject" defaultValue="Product enquiry"><option>Product enquiry</option><option>Size and fit</option><option>Delivery update</option><option>Exchange support</option><option>Something else</option></select></label><label>Your message<textarea name="message" rows="4" placeholder="Write your message..." minLength="5" maxLength="3000" required/></label>{notice&&<p className="form-hint" role="status" style={{color:noticeError?'#a21d1d':'#26703a'}}>{notice}</p>}<button className="button button-dark" type="submit" disabled={sending}>{sending?'Sending…':'Send your message'} <ArrowUpRight/></button></form></div></div>}

function PhoneIcon(){return <span className="phone-symbol">⌕</span>}
function JournalPage(){const stories=[['The art of a thoughtful wardrobe','Build a collection that feels personal, versatile and entirely your own.','https://images.unsplash.com/photo-1483985988355-763728e1935b?w=1100'],['A little guide to occasion dressing','Find the balance between feeling special and feeling like yourself.','https://images.unsplash.com/photo-1539109136881-3be0616acf4b?w=1100'],['The beauty of the finishing touch','Small details have a lovely way of changing the whole look.','https://images.unsplash.com/photo-1535632066927-ab7c9ab60908?w=1100']];return <div className="page-wrap journal-page"><div className="shop-intro"><span className="eyebrow">THE AZMEYRA JOURNAL</span><h1>Notes on <em>style.</em></h1><p>Ideas, inspiration and thoughtful ways to wear what you love.</p></div><div className="journal-grid">{stories.map((story,index)=><article key={story[0]}><img src={story[2]} alt={story[0]} loading="lazy"/><span className="eyebrow">STYLE NOTES · 0{index+1}</span><h2>{story[0]}</h2><p>{story[1]}</p><span className="journal-read">A LITTLE INSPIRATION <ArrowUpRight/></span></article>)}</div></div>}

