 const uploadWelcomeImage=async ev=>{ev.preventDefault();const uploadForm=ev.currentTarget;if(!welcomeFile)return fail('Please choose an image first.');if(!['image/jpeg','image/png','image/webp'].includes(welcomeFile.type))return fail('Use JPG, PNG or WEBP image.');if(welcomeFile.size>10*1024*1024)return fail('Image must be 10 MB or smaller.');setWelcomeUploading(true);try{const ext=welcomeFile.name.split('.').pop().toLowerCase().replace(/[^a-z0-9]/g,'')||'jpg';const path='welcome-popup/'+crypto.randomUUID()+'.'+ext;const {error:uploadError}=await supabase.storage.from('welcome-images').upload(path,welcomeFile,{contentType:welcomeFile.type,cacheControl:'3600',upsert:false});if(uploadError)throw uploadError;const url=supabase.storage.from('welcome-images').getPublicUrl(path).data.publicUrl;const {error:saveError}=await supabase.from('site_settings').upsert({key:'welcome_popup_image',value:url,updated_at:new Date().toISOString()},{onConflict:'key'});if(saveError)throw saveError;onWelcomeImageChange(url);setWelcomeFile(null);uploadForm.reset();notify('Welcome popup image updated successfully.');}catch(e){fail('Could not update welcome image: '+e.message);}finally{setWelcomeUploading(false);}};
