 const orderStatusOptions=[['received','Pending'],['confirmed','Confirmed'],['processing','Processing'],['shipped','Shipped'],['delivered','Delivered'],['cancelled','Cancelled']];const orderStatusLabel=s=>orderStatusOptions.find(([v])=>v===s)?.[1]||s;
